  `prop_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '属性键名（如“appid”“营业时间”）',
  `prop_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '属性值',
  `value_type` enum('input','textarea') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '值类型（如 “input\",\"textarea\",\"select\"用于数据解析时的类型转换',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '字段说明',
  `type_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型标签（如“payment”“retail”）',
  `sort` int(11) NULL DEFAULT 0,
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '软删除时间戳',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  UNIQUE INDEX `prop_key_type_tag`(`prop_key`, `type_tag`) USING BTREE,
  INDEX `idx_type_tag`(`type_tag`) USING BTREE,
  INDEX `idx_name`(`name`) USING BTREE,
  INDEX `idx_prop_key`(`prop_key`) USING BTREE,
  INDEX `idx_delete_at`(`deleted_at`) USING BTREE,
  INDEX `type_tag_sort`(`type_tag`, `sort`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '动态属性表（用于存储各行业/业务的变动性字段）' ROW_FORMAT = DYNAMIC;

