  `description` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '描述$textarea',
  `url` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'URL路径',
  `method` int(11) NOT NULL DEFAULT 1 COMMENT '请求方式:1-get,2-post,4-put,8-delete,16-head,32-options,64-trace,128-connect$checkbox@required|array',
  `is_page` int(11) NOT NULL DEFAULT 0 COMMENT '是否为页面:0-否,1-是$radio@in:0,1',
  `disabled` tinyint(4) NOT NULL DEFAULT 0 COMMENT '功能状态:0-启用,1-禁用$radio@in:0,1',
  `status` tinyint(4) NOT NULL DEFAULT 2 COMMENT '状态:1-显示,2-不显示$radio@in:1,2',
  `level` smallint(6) NOT NULL DEFAULT 0 COMMENT '层级',
  `left_margin` int(11) NOT NULL DEFAULT 0 COMMENT '左边界',
  `right_margin` int(11) NOT NULL DEFAULT 0 COMMENT '右边界',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `group` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '后台路由所属组',
  `action` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '绑定控制器方法',
  `env` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '使用环境',
  `plug_in_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件菜单唯一标识',
  `use` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '路由使用地方:1-api,2-web',
  `as` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '路由别名',
  `middleware` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '单独使用中间件',
  `item_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '资源名称',
  `is_out_link` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为外部链接:0-否,1-是',
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'ID',
  `parent_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '父级ID@sometimes|required|exists:menus,id',
  `resource_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '所属资源',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `menus_left_margin_index`(`left_margin`) USING BTREE,
  INDEX `menus_right_margin_index`(`right_margin`) USING BTREE,
  INDEX `menus_parent_id_index`(`parent_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '菜单$softDeletes,timestamps' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of menus
-- ----------------------------

-- ----------------------------
-- Table structure for messages
-- ----------------------------
DROP TABLE IF EXISTS `messages`;
CREATE TABLE `messages`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID$select2@nullable|exists:users,id',
  `type` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型:0-提醒,1-消息,2-重要$icheckRadio@required|in:0,1,2',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标题@required',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '内容$markdown',
  `operate_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作者',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `messages_user_id_index`(`user_id`) USING BTREE,
  INDEX `messages_operate_id_index`(`operate_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of messages
-- ----------------------------

-- ----------------------------
-- Table structure for migrations
-- ----------------------------
DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `migration` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch` int(11) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of migrations
-- ----------------------------

-- ----------------------------
-- Table structure for orders
-- ----------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '唯一标识',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '用户ID',
  `sub_union_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子渠道标识',
  `sku_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `short_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'shortURL',
  `字段 30` int(11) NULL DEFAULT NULL,
  `order_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `sku_num` int(11) NOT NULL DEFAULT 0 COMMENT '商品数量',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '单价',
  `total_price` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `sku_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SKU ID',
  `valid_code` tinyint(4) NOT NULL DEFAULT 0 COMMENT '下单状态,-1：未知, 3.无效-取消, ,15.待付款,16.已付款,17.已完成（购买用户确认收货）, 24.已付定金,',
  `express_status` tinyint(2) NOT NULL DEFAULT 0 COMMENT '发货',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SKU主图链接',
  `owner` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所有者',
  `shop_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '店铺名称',
  `commission_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '佣金比例(%)',
  `sub_side_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '分成比例(%)',
  `subsidy_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '补贴比例(%)',
  `final_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '最终分佣比例(%)',
  `estimate_cos_price` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '预估计佣金额,客户说是‘用户实际付款金额’',
  `estimate_fee` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '推客的预估佣金，这个重要',
  `actual_cos_price` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '实际计算佣金的金额',
  `actual_fee` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '推客分得的实际佣金，这个重要',
  `order_time` datetime NOT NULL COMMENT '下单时间',
  `modify_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  `order_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '订单JSON数据',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_id`(`order_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_created_at`(`created_at`) USING BTREE,
  INDEX `idx_finish_time`(`finish_time`) USING BTREE,
  INDEX `valid_code`(`valid_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of orders
-- ----------------------------

-- ----------------------------
-- Table structure for orders_copy
-- ----------------------------
DROP TABLE IF EXISTS `orders_copy`;
CREATE TABLE `orders_copy`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '唯一标识',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '用户ID',
  `sub_union_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子渠道标识',
  `sku_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `order_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `sku_num` int(10) NOT NULL DEFAULT 0 COMMENT '商品数量',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '单价',
  `total_price` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `sku_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SKU ID',
  `valid_code` int(5) NOT NULL DEFAULT 0 COMMENT '下单状态',
  `express_status` tinyint(2) NOT NULL DEFAULT 0 COMMENT '发货',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SKU主图链接',
  `owner` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所有者',
  `shop_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '店铺名称',
  `commission_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '佣金比例(%)',
  `sub_side_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '分成比例(%)',
  `subsidy_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '补贴比例(%)',
  `final_rate` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '最终分佣比例(%)',
  `estimate_cos_price` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '预估计佣金额',
  `estimate_fee` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '推客的预估佣金',
  `actual_cos_price` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '实际计算佣金的金额',
  `actual_fee` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '推客分得的实际佣金',
  `order_time` datetime NOT NULL COMMENT '下单时间',
  `modify_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  `order_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '订单JSON数据',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_id`(`order_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_created_at`(`created_at`) USING BTREE,
  INDEX `idx_finish_time`(`finish_time`) USING BTREE,
  INDEX `valid_code`(`valid_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of orders_copy
-- ----------------------------

-- ----------------------------
-- Table structure for password_resets
-- ----------------------------
DROP TABLE IF EXISTS `password_resets`;
CREATE TABLE `password_resets`  (
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  INDEX `password_resets_email_index`(`email`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of password_resets
-- ----------------------------

-- ----------------------------
-- Table structure for personal_access_tokens
-- ----------------------------
DROP TABLE IF EXISTS `personal_access_tokens`;
CREATE TABLE `personal_access_tokens`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `tokenable_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tokenable_id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `abilities` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `personal_access_tokens_token_unique`(`token`) USING BTREE,
  INDEX `personal_access_tokens_tokenable_type_tokenable_id_index`(`tokenable_type`, `tokenable_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 430 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of personal_access_tokens
-- ----------------------------

-- ----------------------------
-- Table structure for product_category
-- ----------------------------
DROP TABLE IF EXISTS `product_category`;
CREATE TABLE `product_category`  (
  `id` int(11) NOT NULL COMMENT '主键ID',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型名称',
  `parent_id` int(11) NOT NULL DEFAULT 0 COMMENT '父类ID（0表示顶级类型）',
  `brands` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `level` tinyint(1) NOT NULL DEFAULT 1 COMMENT '层级（1=顶级，2=二级，以此类推）',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序权重（数字越大越靠前）',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态（1=启用，0=禁用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE,
  INDEX `idx_level`(`level`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_category
-- ----------------------------

-- ----------------------------
-- Table structure for product_detail
-- ----------------------------
DROP TABLE IF EXISTS `product_detail`;
CREATE TABLE `product_detail`  (
  `id` int(11) NOT NULL COMMENT '主键',
  `number` int(11) NOT NULL COMMENT '商品编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `price` decimal(10, 2) NOT NULL COMMENT '销售价格',
  `money` decimal(10, 2) NOT NULL COMMENT '原价/金额',
  `type` tinyint(4) NOT NULL COMMENT '类型标识',
  `day` int(11) NOT NULL DEFAULT 0 COMMENT '天数',
  `min` int(11) NOT NULL COMMENT '最小购买数量',
  `max` int(11) NOT NULL COMMENT '最大购买数量',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述（短）',
  `describe` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '详细描述',
  `accountName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账号名称（如QQ号码）',
  `accountType` tinyint(4) NOT NULL COMMENT '账号类型',
  `accountType1` tinyint(4) NOT NULL DEFAULT 0 COMMENT '账号类型扩展',
  `accountDesc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '账号描述',
  `accountContent` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '账号内容',
  `accountRequired` tinyint(4) NOT NULL COMMENT '是否必填账号（1=是，0=否）',
  `accountRegex` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `count` int(11) NOT NULL COMMENT '库存数量',
  `TagName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '标签名称',
  `TagColor` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '标签颜色',
  `imgs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片URL（JSON格式存储多图）',
  `discounts` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '折扣信息',
  `templates` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '模板信息',
  `mainKey` tinyint(4) NOT NULL DEFAULT 0 COMMENT '主标识',
  `status` tinyint(4) NOT NULL COMMENT '状态（1=启用，0=禁用）',
  `multiple` int(11) NOT NULL COMMENT '倍数',
  `isRepeat` tinyint(4) NOT NULL COMMENT '是否允许重复购买（1=是，0=否）',
  `skuType` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'SKU类型',
  `skus` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'SKU列表（JSON格式）',
  `skuDetails` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'SKU详情（JSON格式）',
  `specs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '规格信息（JSON格式）',
  `brands` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌信息',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'QQ会员月卡商品表\r\nproduct.number = product_detail.number \r\n1对多的关系' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_detail
-- ----------------------------

-- ----------------------------
-- Table structure for products
-- ----------------------------
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '商品编号',
  `price` decimal(10, 2) NOT NULL COMMENT '商品面值',
  `platform_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '平台价,网站的销售价格',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `money` decimal(10, 2) NOT NULL COMMENT '购买价格',
  `day` int(11) NOT NULL DEFAULT 0 COMMENT '质保天数（0为无限制）',
  `type` tinyint(4) NOT NULL COMMENT '商品类型（1-卡券/3-直充）',
  `multiple` int(11) NOT NULL DEFAULT 1 COMMENT '发货倍数',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '销售状态（1-销售/2-暂停/3-禁售）',
  `isRepeat` tinyint(4) NOT NULL DEFAULT 0 COMMENT '重复下单（0-不允许/1-允许）',
  `skuType` tinyint(4) NOT NULL DEFAULT 0 COMMENT '规格类型（0-单规格/1-多规格/2-多单规格）',
  `dirIds` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联分类ID（JSON数组）',
  `dirId1` int(10) NULL DEFAULT 0,
  `dirId2` int(10) NULL DEFAULT 0,
  `dirId3` int(10) NULL DEFAULT 0,
  `imgUrl` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `isRefOrder` int(10) NULL DEFAULT 0,
  `keyId` int(10) NULL DEFAULT 0,
  `isRefMoney` int(10) NULL DEFAULT 0,
  `number` int(11) NULL DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE,
  INDEX `idx_created_at`(`created_at`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13472 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of products
-- ----------------------------

-- ----------------------------
-- Table structure for promotions
-- ----------------------------
DROP TABLE IF EXISTS `promotions`;
CREATE TABLE `promotions`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT '用户ID，推荐注册成功的新用户，子关系',
  `referred_by` bigint(20) NULL DEFAULT NULL COMMENT '推荐人ID，父关系',
  `referral_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '推荐码',
  `registration_time` datetime NOT NULL COMMENT '注册时间',
  `reward_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '奖励余额',
  `reward_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '奖励状态：0=待发放，1=已发放，2=已失效',
  `reward_time` datetime NULL DEFAULT NULL COMMENT '奖励发放时间',
  `created_at` timestamp NULL DEFAULT NULL COMMENT '记录创建时间',
  `updated_at` timestamp NULL DEFAULT NULL COMMENT '记录更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_user_id`(`user_id`) USING BTREE,
  INDEX `idx_referred_by`(`referred_by`) USING BTREE,
  INDEX `idx_referral_code`(`referral_code`) USING BTREE,
  INDEX `idx_registration_time`(`registration_time`) USING BTREE,
  INDEX `idx_reward_status`(`reward_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户推广关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of promotions
-- ----------------------------

-- ----------------------------
-- Table structure for recharge_records
-- ----------------------------
DROP TABLE IF EXISTS `recharge_records`;
CREATE TABLE `recharge_records`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT '用户ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `third_party_order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方的订单号',
  `handling_fee` decimal(10, 6) NULL DEFAULT NULL COMMENT '手续费',
  `amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '充值金额',
  `total_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '手续费+充值金额',
  `payment_method` tinyint(4) NOT NULL DEFAULT 1 COMMENT '支付方式:1-微信,2-支付宝',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '状态:0-待支付,1-支付成功,2-支付失败',
  `payment_time` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `errormsg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_order_no`(`order_no`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_created_at`(`created_at`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10071 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '充值记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of recharge_records
-- ----------------------------

-- ----------------------------
-- Table structure for uploaded_files
-- ----------------------------
DROP TABLE IF EXISTS `uploaded_files`;
CREATE TABLE `uploaded_files`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 64 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of uploaded_files
-- ----------------------------

-- ----------------------------
-- Table structure for user_balance_log
-- ----------------------------
DROP TABLE IF EXISTS `user_balance_log`;
CREATE TABLE `user_balance_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT '用户ID',
  `order_id` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '关联订单ID',
  `transaction_type` tinyint(4) NOT NULL COMMENT '交易类型(1:支付 2:充值 3:提现 4:其他)',
  `amount` decimal(10, 2) NOT NULL COMMENT '变动金额',
  `balance_before` decimal(10, 2) NOT NULL COMMENT '变动前余额',
  `balance_after` decimal(10, 2) NOT NULL COMMENT '变动后余额',
  `transaction_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易流水号',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_order_id`(`order_id`) USING BTREE,
  INDEX `idx_transaction_no`(`transaction_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户余额流水表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_balance_log
-- ----------------------------

-- ----------------------------
-- Table structure for user_commission_settlement
-- ----------------------------
DROP TABLE IF EXISTS `user_commission_settlement`;
CREATE TABLE `user_commission_settlement`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键，唯一标识每条结算记录',
  `user_id` int(11) NOT NULL COMMENT '用户ID，关联到用户表(users)的主键id，标识该笔佣金所属的用户',
  `bill_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账单编号，如截图中的202502账单',
  `after_tax_income` decimal(10, 2) NULL DEFAULT NULL COMMENT '税后收益',
  `settlement_year` int(11) NOT NULL DEFAULT 0,
  `settlement_month` tinyint(2) NULL DEFAULT 0,
  `general_commission` decimal(10, 2) NOT NULL COMMENT '通用佣金',
  `reward_commission` decimal(10, 2) NULL DEFAULT NULL COMMENT '奖励佣金',
  `pre_tax_amount` decimal(10, 2) NOT NULL COMMENT '税前金额',
  `total_tax` decimal(10, 2) NOT NULL COMMENT '综合税金',
  `is_paid` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已经打款，布尔值表示：0-未打款，1-已打款，默认值为0（未打款）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注说明，用于记录该笔结算的特殊信息，如优惠活动、调整原因等',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间，自动生成，无需手动插入',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间，当记录被修改时自动更新',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE COMMENT '用户ID索引，用于快速查询特定用户的所有结算记录',
  INDEX `idx_is_paid`(`is_paid`) USING BTREE COMMENT '打款状态索引，用于快速筛选未打款或已打款的记录',
  INDEX `idx_bill_no`(`bill_no`) USING BTREE COMMENT '账单编号索引，用于快速根据账单编号查询记录'
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户佣金结算表，存储所有用户的佣金结算记录及相关状态信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_commission_settlement
-- ----------------------------

-- ----------------------------
-- Table structure for user_withdrawal_records
-- ----------------------------
DROP TABLE IF EXISTS `user_withdrawal_records`;
CREATE TABLE `user_withdrawal_records`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '提现记录ID',
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT '用户ID',
  `withdrawal_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提现单号',
  `third_party_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方支付订单号',
  `amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现金额',
  `handling_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '手续费',
  `actual_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际到账金额',
  `pay_account_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账户名称',
  `pay_account_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `wx_package_info` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信支付包的信息',
  `withdrawal_type` tinyint(4) NULL DEFAULT NULL COMMENT '1-支付宝，2-微信',
  `withdrawal_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '提现状态:0-待处理,1-已到账,2-失败,3-未确认收款(微信)',
  `withdrawal_time` timestamp NULL DEFAULT NULL COMMENT '提现申请时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `arrival_time` timestamp NULL DEFAULT NULL COMMENT '到账时间',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_withdrawal_no`(`withdrawal_no`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_withdrawal_status`(`withdrawal_status`) USING BTREE,
  INDEX `idx_withdrawal_time`(`withdrawal_time`) USING BTREE,
  INDEX `idx_third_party_order_no`(`third_party_order_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10041 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户提现记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_withdrawal_records
-- ----------------------------

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `phone` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `remember_token` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `status` tinyint(2) NOT NULL DEFAULT 1 COMMENT '0表示禁用，1表示有效',
  `sub_union_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '1表示禁用',
  `balance` decimal(10, 2) NULL DEFAULT NULL,
  `wechat_openid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `invitation_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '推荐码',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bank_real_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '姓名',
  `id_card` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '身份证',
  `bank_card` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '银行卡号',
  `bank_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '银行卡预留电话',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `phone`(`phone`) USING BTREE,
  UNIQUE INDEX `wechat_openid`(`wechat_openid`) USING BTREE,
  UNIQUE INDEX `invitation_code`(`invitation_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1003 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of users
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
